PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS rc_branches (id TEXT PRIMARY KEY, name TEXT NOT NULL, bank_account TEXT NOT NULL, bank_code TEXT NOT NULL, bank_name TEXT NOT NULL, sub_account TEXT NOT NULL DEFAULT '', qr_mode TEXT NOT NULL DEFAULT 'direct' CHECK(qr_mode IN ('direct','virtual','memo')), transfer_prefix TEXT NOT NULL DEFAULT '', credential_context TEXT NOT NULL, environment TEXT NOT NULL CHECK(environment IN ('sandbox','live')), issuer_json TEXT NOT NULL CHECK(json_valid(issuer_json)), version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rc_members (branch_id TEXT NOT NULL REFERENCES rc_branches(id), user_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('manager','floor','kitchen','cashier','accountant')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(branch_id,user_id));
CREATE INDEX IF NOT EXISTS rc_members_user ON rc_members(user_id,branch_id);
CREATE TABLE IF NOT EXISTS rc_tables (id TEXT PRIMARY KEY, branch_id TEXT NOT NULL REFERENCES rc_branches(id), name TEXT NOT NULL, token TEXT NOT NULL UNIQUE, version INTEGER NOT NULL DEFAULT 1, UNIQUE(branch_id,name));
CREATE TABLE IF NOT EXISTS rc_visits (id TEXT PRIMARY KEY, branch_id TEXT NOT NULL REFERENCES rc_branches(id), table_id TEXT NOT NULL REFERENCES rc_tables(id), status TEXT NOT NULL CHECK(status IN ('open','billing','paid','closed')), version INTEGER NOT NULL DEFAULT 1, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, closed_at INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS rc_visit_active ON rc_visits(table_id) WHERE status <> 'closed';
CREATE INDEX IF NOT EXISTS rc_visits_branch ON rc_visits(branch_id,id);
CREATE TABLE IF NOT EXISTS rc_guest_sessions (token_hash TEXT PRIMARY KEY, visit_id TEXT NOT NULL REFERENCES rc_visits(id), created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rc_menu (id TEXT PRIMARY KEY, branch_id TEXT NOT NULL REFERENCES rc_branches(id), name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, image TEXT NOT NULL, price INTEGER NOT NULL CHECK(price >= 0 AND price <= 9000000000000), tax_rate INTEGER NOT NULL CHECK(tax_rate BETWEEN 0 AND 10000), available INTEGER NOT NULL CHECK(available IN (0,1)), modifiers_json TEXT NOT NULL CHECK(json_valid(modifiers_json)), version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS rc_menu_branch ON rc_menu(branch_id,id);
CREATE TABLE IF NOT EXISTS rc_orders (id TEXT PRIMARY KEY, branch_id TEXT NOT NULL REFERENCES rc_branches(id), visit_id TEXT NOT NULL REFERENCES rc_visits(id), status TEXT NOT NULL CHECK(status IN ('pending','confirmed','rejected','voided')), note TEXT NOT NULL, reason TEXT, total INTEGER NOT NULL CHECK(total BETWEEN 0 AND 9000000000000), version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS rc_orders_visit ON rc_orders(visit_id,status,id);
CREATE INDEX IF NOT EXISTS rc_orders_branch ON rc_orders(branch_id,id);
CREATE TABLE IF NOT EXISTS rc_order_lines (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES rc_orders(id), menu_item_id TEXT NOT NULL REFERENCES rc_menu(id), name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 100), unit_price INTEGER NOT NULL CHECK(unit_price BETWEEN 0 AND 9000000000000), tax_rate INTEGER NOT NULL CHECK(tax_rate BETWEEN 0 AND 10000), modifiers_json TEXT NOT NULL CHECK(json_valid(modifiers_json)), total INTEGER NOT NULL CHECK(total BETWEEN 0 AND 9000000000000), tax_amount INTEGER NOT NULL CHECK(tax_amount >= 0), kitchen_status TEXT NOT NULL DEFAULT 'queued' CHECK(kitchen_status IN ('queued','preparing','ready','served')), version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS rc_lines_order ON rc_order_lines(order_id,id);
CREATE TABLE IF NOT EXISTS rc_payment_attempts (id TEXT PRIMARY KEY, branch_id TEXT NOT NULL REFERENCES rc_branches(id), visit_id TEXT NOT NULL REFERENCES rc_visits(id), reference TEXT NOT NULL UNIQUE, amount INTEGER NOT NULL CHECK(amount > 0 AND amount <= 9000000000000), bank_account TEXT NOT NULL, bank_code TEXT NOT NULL, bank_name TEXT NOT NULL DEFAULT '', sub_account TEXT NOT NULL DEFAULT '', qr_mode TEXT NOT NULL DEFAULT 'direct' CHECK(qr_mode IN ('direct','virtual','memo')), transfer_prefix TEXT NOT NULL DEFAULT '', credential_context TEXT NOT NULL, environment TEXT NOT NULL CHECK(environment IN ('sandbox','live')), status TEXT NOT NULL CHECK(status IN ('pending','paid','superseded','exception')), created_at INTEGER NOT NULL, paid_at INTEGER, version INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS rc_payment_pending ON rc_payment_attempts(visit_id) WHERE status='pending';
CREATE INDEX IF NOT EXISTS rc_payments_branch ON rc_payment_attempts(branch_id,id);
CREATE TABLE IF NOT EXISTS rc_invoices (id TEXT PRIMARY KEY, branch_id TEXT NOT NULL REFERENCES rc_branches(id), visit_id TEXT NOT NULL REFERENCES rc_visits(id), payment_id TEXT NOT NULL REFERENCES rc_payment_attempts(id), kind TEXT NOT NULL CHECK(kind IN ('original','adjustment','replacement')), original_invoice_id TEXT REFERENCES rc_invoices(id), status TEXT NOT NULL CHECK(status IN ('queued','dispatching','pending','draft','issued','cancelled','failed','outcome_unknown')), reference TEXT NOT NULL UNIQUE, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), issuer_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(issuer_json)), issue_payload_json TEXT, credential_context TEXT NOT NULL, environment TEXT NOT NULL, create_tracking_code TEXT, issue_tracking_code TEXT, provider_id TEXT, provider_json TEXT, tax_authority_status TEXT, dispatch_token TEXT, dispatch_at INTEGER, last_operation TEXT, last_error TEXT, version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS rc_original_invoice ON rc_invoices(payment_id) WHERE kind='original';
CREATE INDEX IF NOT EXISTS rc_invoices_branch ON rc_invoices(branch_id,id);
CREATE TABLE IF NOT EXISTS rc_audit (id TEXT PRIMARY KEY, branch_id TEXT NOT NULL REFERENCES rc_branches(id), actor_id TEXT, action TEXT NOT NULL, entity_id TEXT NOT NULL, detail_json TEXT NOT NULL CHECK(json_valid(detail_json)), created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS rc_audit_branch_date ON rc_audit(branch_id,created_at,id);
CREATE TABLE IF NOT EXISTS rc_commands (scope TEXT NOT NULL, id TEXT NOT NULL, payload_hash TEXT NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json)), created_at INTEGER NOT NULL, PRIMARY KEY(scope,id));
CREATE TABLE IF NOT EXISTS rc_assertions (id TEXT PRIMARY KEY, ok INTEGER NOT NULL CONSTRAINT rc_guard CHECK(ok = 1));
CREATE TABLE IF NOT EXISTS rc_outbox (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','running','done','review')), attempts INTEGER NOT NULL DEFAULT 0, available_at INTEGER NOT NULL, lease_token TEXT, lease_until INTEGER, last_error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS rc_outbox_due ON rc_outbox(state,available_at,lease_until);
CREATE TABLE IF NOT EXISTS rc_payment_inbox (id TEXT PRIMARY KEY, environment TEXT NOT NULL, credential_context TEXT NOT NULL, provider_transaction_id TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), state TEXT NOT NULL DEFAULT 'pending', exception TEXT, payment_id TEXT, created_at INTEGER NOT NULL, processed_at INTEGER, UNIQUE(environment,credential_context,provider_transaction_id));
CREATE TABLE IF NOT EXISTS rc_payment_allocations (id TEXT PRIMARY KEY, inbox_id TEXT NOT NULL UNIQUE REFERENCES rc_payment_inbox(id), payment_id TEXT NOT NULL UNIQUE REFERENCES rc_payment_attempts(id), amount INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rc_bank_reconciliation (id TEXT PRIMARY KEY, environment TEXT NOT NULL, credential_context TEXT NOT NULL, provider_transaction_id TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), state TEXT NOT NULL, matched_inbox_id TEXT, created_at INTEGER NOT NULL, UNIQUE(environment,credential_context,provider_transaction_id));
